python3 << 'PYEOF'
import json, yaml

fpath = "/home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-14-projects-distill-sparse-swiglu--claude-sessions-paper-agent-f4a39553/f9ea8332-50c6-48e4-97b8-2733fa7a85f9/tool-results/mcp-agent-ml-research-read_registry-1779697873709.txt"

with open(fpath, 'r') as f:
    raw = f.read()

data = json.loads(raw)
result_yaml = data['result']
registry = yaml.safe_load(result_yaml)
exps = registry['data']['experiments']

# Get the oracle and ste experiments with full details
for eid in ['kl_bce_f1_oracle', 'ste_baseline_s42', 'ste_30_s42', 'jsd_50pct_s42', 'reverse_kl_50pct_s42', 
            'perlayer_kl_k4_50_s42', 'perlayer_kl_50_s42_downstream', 'bench_teal50_uniform_gsm8k',
            'mse30_s42_boolq', 'bce_gumbel_lagrangian_isolation']:
    if eid in exps:
        exp = exps[eid]
        print(f"\n=== {eid} ===")
        print(f"  status: {exp.get('status')}")
        print(f"  metrics: {json.dumps(exp.get('metrics', {}), indent=4, default=str)}")
        if 'conclusion' in exp:
            print(f"  conclusion: {exp['conclusion'][:200]}")
        if 'notes' in exp:
            print(f"  notes: {str(exp['notes'])[:200]}")
        if 'teal_sparse_ppl' in exp:
            print(f"  teal_sparse_ppl: {exp['teal_sparse_ppl']}")

# Also check for mse30_s42 variants
print("\n\n=== mse30_s42* variants ===")
for eid in sorted(exps.keys()):
    if 'mse30_s42' in eid or 'mse30_uniform' in eid:
        exp = exps[eid]
        m = exp.get('metrics', {}) or {}
        print(f"  {eid}: status={exp['status']} metrics={json.dumps(m, default=str)[:300]}")

# Check bench_kl30_global and related
print("\n\n=== kl30 global variants ===")
for eid in sorted(exps.keys()):
    if 'kl30' in eid and 'global' in eid:
        exp = exps[eid]
        m = exp.get('metrics', {}) or {}
        print(f"  {eid}: status={exp['status']} metrics={json.dumps(m, default=str)[:300]}")

# Check bench_teal30_uniform more thoroughly
print("\n\n=== teal30 all ===")
for eid in sorted(exps.keys()):
    if 'teal30' in eid:
        exp = exps[eid]
        m = exp.get('metrics', {}) or {}
        print(f"  {eid}: status={exp['status']} metrics={json.dumps(m, default=str)[:300]}")

# Check bce_iso variants
print("\n\n=== bce_iso variants ===")
for eid in sorted(exps.keys()):
    if 'bce_iso' in eid:
        exp = exps[eid]
        m = exp.get('metrics', {}) or {}
        print(f"  {eid}: metrics={json.dumps(m, default=str)[:300]}")
PYEOF

